 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // --- FormatPhoneNumber ---

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParentheses()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         StringAssert.StartsWith(result, "(555)");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         StringAssert.EndsWith(result, "4567");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ContainsDashSeparator()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         StringAssert.Contains(result, "-");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsCorrectFormat()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.AreEqual("(555) 123-4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
     {
         Assert.ThrowsException<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));
     }

     [TestMethod]
     [DataRow("123")]
     [DataRow("12345678901")]
     [DataRow("")]
     public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsException<ArgumentException>(
             () => _formatter.FormatPhoneNumber(digits));
     }

     // --- BuildGreeting ---

     [TestMethod]
     public void BuildGreeting_WithDefaultTitle_StartsWithDearMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         StringAssert.StartsWith(result, "Dear Mr.");
     }

     [TestMethod]
     public void BuildGreeting_AnyInput_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         StringAssert.EndsWith(result, ",");
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_StartsWithDearAndTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         StringAssert.StartsWith(result, "Dear Dr.");
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_ContainsName()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         StringAssert.Contains(result, "Johnson");
     }

     [TestMethod]
     public void BuildGreeting_ValidInput_ReturnsCorrectFormat()
     {
         var result = _formatter.BuildGreeting("Smith", "Ms.");

         Assert.AreEqual("Dear Ms. Smith,", result);
     }

     [TestMethod]
     public void BuildGreeting_NullName_ThrowsArgumentNullException()
     {
         Assert.ThrowsException<ArgumentNullException>(
             () => _formatter.BuildGreeting(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_EmptyOrWhitespaceName_ThrowsArgumentException(string name)
     {
         Assert.ThrowsException<ArgumentException>(
